      { n: 2, c: "F", de: "Die Wiese beginnt um 8 Uhr……", ar: "تبدأ الحديقة في الساعة 8...", ma: "الحديقة كتبدا فالساعة 8..." },
      { n: 3, c: "R", de: "Eintrittskarten für Jugendliche kosten 13,50 €", ar: "تذاكر الدخول للشباب تكلف 13.50 يورو.", ma: "تذاكر الدخول للشباب كتكلف 13.50 يورو." },
      { n: 4, c: "R", de: "Die Fahrkarte ist in bestimmten Zügen gültig.", ar: "تذكرة السفر صالحة في قطارات معينة.", ma: "تذكرة السفر صالحة فشي قطارات معينة." },
      { n: 5, c: "R", de: "Am Sonntag können Kinder ein Theaterstück anschauen", ar: "يوم الأحد، يمكن للأطفال مشاهدة مسرحية.", ma: "نهار الأحد، الدراري يقدرو يشوفو مسرحية." }
